<?php
require_once __DIR__.'/lib/auth.php';requireAuth();if($_SERVER['REQUEST_METHOD']!=='POST'||!verifyCsrf($_POST['csrf']??'')){http_response_code(403);exit('Invalid request.');}$name=trim($_POST['organization_name']??'');$domain=mb_strtolower(trim($_POST['organization_domain']??''));$domain=preg_replace('#^https?://#i','',$domain);$domain=rtrim($domain,'/');if($domain!==''&&!filter_var('https://'.$domain,FILTER_VALIDATE_URL)){header('Location: settings.php?branding=invalid');exit;}if($name===''){header('Location: settings.php?branding=invalid');exit;}try{$logo=db()->query('SELECT logo_path FROM organization_settings WHERE id=1')->fetchColumn()?:null;if(isset($_FILES['logo'])&&$_FILES['logo']['error']!==UPLOAD_ERR_NO_FILE){$file=$_FILES['logo'];if($file['error']!==UPLOAD_ERR_OK||$file['size']>2097152)throw new RuntimeException('Invalid logo.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$extensions=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'];if(!isset($extensions[$mime]))throw new RuntimeException('Invalid logo format.');$dir=__DIR__.'/uploads/branding';if(!is_dir($dir))mkdir($dir,0770,true);$filename='logo-'.bin2hex(random_bytes(8)).'.'.$extensions[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$filename))throw new RuntimeException('Logo storage failed.');$logo='uploads/branding/'.$filename;}$s=db()->prepare('INSERT INTO organization_settings(id,name,domain,logo_path) VALUES(1,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),domain=VALUES(domain),logo_path=VALUES(logo_path)');$s->execute([$name,$domain?:null,$logo]);header('Location: settings.php?branding=saved');}catch(Throwable $e){header('Location: settings.php?branding=failed');}
